const fn = new Function(code + "\nreturn { withDeadline };");
const { withDeadline } = fn();
let fallbackRan = false;
const out = await withDeadline(new Promise((r) => setTimeout(() => r("late"), 100)), 20, () => { fallbackRan = true; return "deadline"; });
if (out !== "deadline") throw new Error("A task that misses the deadline resolves with onTimeout's result.");
if (!fallbackRan) throw new Error("onTimeout should actually be called.");
